from torch.utils.data import Dataset

class SquareDataset(Dataset):
    def __init__(self, n):
        self.n = n
    def __len__(self):
        return self.n
    def __getitem__(self, idx):
        x = torch.tensor(idx, dtype=torch.float32)
        y = x ** 2
        return x, y

ds = SquareDataset(5)
print(len(ds))   # 5
print(ds[3])     # (3.0, 9.0)

